import './ui/styles.css';
import './ui/operations.css';
import './ui/explore.css';
import {operationsHTML,requestHTML,selectedOperationsHTML,drawGroundDebug,duration,type GroundDebugOptions} from './ui/operations';
import {routineEnabled} from './sim/difficulty';
import {explorationScenario} from './sim/exploration';
import { Simulation } from './sim/Simulation';
import type { AirportScene } from './render/AirportScene';
import {primaryExploreSpots,detailExploreSpots,type ExploreSpotId} from './render/exploration';
import { FLEET, AIRLINES } from './data/fleet';
import { airport, airportSource } from './data/airport';
import { hasOfficialSchedule, OFFICIAL_SCHEDULE_CAPTURED_AT, OFFICIAL_SCHEDULE_COUNT, OFFICIAL_SCHEDULE_DATE } from './data/schedule';
import { AirportAudio } from './audio';
import { translate, commandLabel, stateLabel, type Language } from './ui/i18n';
import type { Aircraft, CameraMode, Command, Role, Scenario, WeatherKind } from './types';

const $=<T extends HTMLElement=HTMLElement>(selector:string)=>document.querySelector<T>(selector)!;
const esc=(text:unknown)=>String(text??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const stored=<T>(key:string,fallback:T):T=>{try{return JSON.parse(localStorage.getItem(key)??'null')??fallback;}catch{return fallback;}};
const persist=(key:string,value:unknown)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{/* Private browsing: settings still work for this session. */}};
let lang:Language=stored('atc-language','en');
let quality:'low'|'medium'|'high'=stored('atc-quality','high');
const t=(key:string)=>translate(key,lang);
const carrierName=(id:string)=>{const carrier=AIRLINES[id];return lang==='zh'?(carrier?.localName??carrier?.name??id):(carrier?.name??id);};
const scheduleName=(date:string)=>mode==='training'?bi('Scripted training flights','教學範例航班'):hasOfficialSchedule(date)?bi('Official TPE schedule snapshot','桃園機場官方班表快照'):t('typical');
const scheduleNoteHTML=(date:string)=>mode==='training'?`<strong><span class="status-dot"></span>${bi('Scripted training traffic','教學範例航班')}</strong>${bi('Training uses scripted aircraft and does not load the dated timetable.','教學使用預設範例航機，不載入日期班表。')}`:hasOfficialSchedule(date)?`<strong><span class="status-dot"></span>${bi('Official TPE flight snapshot','桃園機場官方航班快照')} · ${OFFICIAL_SCHEDULE_DATE}</strong>${bi(`${OFFICIAL_SCHEDULE_COUNT} flights · 62 carriers · captured ${OFFICIAL_SCHEDULE_CAPTURED_AT.slice(11,16)} LT. Unpublished models use a clearly marked simulation proxy.`,`${OFFICIAL_SCHEDULE_COUNT} 班 · 62 家航空公司 · ${OFFICIAL_SCHEDULE_CAPTURED_AT.slice(11,16)} 擷取。未公布機型會以模擬代理機型標示。`)}`:`<strong><span class="status-dot"></span>${t('typical')}</strong>${t('typicalNote')}`;
const clock=(seconds:number)=>new Date(((seconds%86400)+86400)%86400*1000).toISOString().slice(11,19);
const shortTime=(seconds:number)=>clock(seconds).slice(0,5);
const flightTimeLabel=(a:Aircraft)=>{if(!a.flightSource||a.publishedScheduledTime===undefined)return shortTime(a.scheduledTime);const scheduled=shortTime(a.publishedScheduledTime),current=shortTime(a.scheduledTime);return scheduled===current?scheduled:lang==='zh'?`表 ${scheduled} · 預 ${current}`:`${scheduled} → ${current}`;};
const flightStatusLabel=(status?:string)=>lang==='zh'?status??'':({準時:'On time',改時:'Rescheduled',出發:'Departed',已到:'Arrived'} as Record<string,string>)[status??'']??status??'';
const logo=`<svg class="logo-mark" viewBox="0 0 40 48" fill="none" aria-hidden="true"><path d="M7 9h26l-4 11H11L7 9Z" stroke="currentColor" stroke-width="1.5"/><path d="M13 10v9m7-9v9m7-9v9M17 21l-3 20h12l-3-20M10 43h20M20 2v6M4 7h32" stroke="currentColor" stroke-width="1.5"/></svg>`;
const logoHTML=()=>`<div class="logo">${logo}<div><strong>${t('tower')}</strong><small>RCTP / 25°04′ N 121°14′ E</small></div></div>`;
const roles:Role[]=['Delivery','Ground','Tower','Approach','Departure'];
const cameras:[CameraMode,string,string][]=[['seat','seat','1'],['walk','walk','2'],['window','window','3'],['free','free','4'],['follow','followCam','5'],['orbit','orbit','6'],['runway','runwayCam','7'],['gate','gateCam','8']];
const weatherOptions:WeatherKind[]=['clear','cloudy','overcast','rain','storm','fog'];
let scenario:Scenario={date:'2026-11-11',startTime:'17:00',duration:15,difficulty:'standard',weather:'cloudy',seed:182731,incidents:'rare',positions:[...roles],tutorial:false,density:1};
let sim=new Simulation({...scenario,difficulty:'assisted',positions:[]});
let running=false,intro=false,selectedId:string|null=null,role:Role='Ground',filter='all',query='',immersive=false,mode='new',graph=false;
let scene:AirportScene;
let sceneReady:Promise<void>,sceneLoaded=false,frameId=0,last:number|undefined;
let uiElapsed=0,detailKey='',listKey='',toastTimer=0;
let tutorialStage=0,tutorialDep:string|null=null,tutorialArr:string|null=null;
let previousScale=1;
let trafficTab:'flights'|'requests'='flights';
let exploreLocation:ExploreSpotId='runway',exploreLabels=false;
const groundDebug:GroundDebugOptions={graph:true,routes:true,nodes:true,edges:true,zones:true,waits:true,owners:true};
const bi=(en:string,zh:string)=>lang==='en'?en:zh;
const audio=new AirportAudio();audio.enabled=stored('atc-audio',true);audio.setVolume(stored('atc-volume',.65));audio.radioVoice=stored('atc-radio-voice',true);
const app=$('#app');

function options(keys:string[],current:string){return keys.map(key=>`<option value="${key}" ${current===key?'selected':''}>${t(key)}</option>`).join('');}
function toast(message:string){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=window.setTimeout(()=>el.remove(),4500);}
function closeModal(){document.querySelector('.modal-backdrop')?.remove();}
function modal(title:string,body:string,footer='',wide=false){closeModal();const wrapper=document.createElement('div');wrapper.className='modal-backdrop';wrapper.innerHTML=`<section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${title}</h2><button class="icon" data-close aria-label="${t('close')}">×</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}</section>`;document.body.append(wrapper);wrapper.querySelector('[data-close]')?.addEventListener('click',closeModal);wrapper.addEventListener('click',e=>{if(e.target===wrapper)closeModal();});wrapper.querySelector('button')?.focus();}
function toggleLanguage(){lang=lang==='en'?'zh':'en';persist('atc-language',lang);document.documentElement.lang=lang==='en'?'en':'zh-Hant';closeModal();if(running){if(mode==='explore')renderExploreHUD();else renderHUD();refreshUI();}else renderMenu();}

function renderMenu(){
  const wasRunning=running;
  running=false;intro=false;immersive=false;last=undefined;audio.stop();scene?.setImmersive(false);closeModal();
  if(wasRunning)requestFrame();
  app.innerHTML=`<main class="menu"><header class="menu-header">${logoHTML()}<nav class="menu-nav"><button id="language">${lang==='en'?'繁體中文':'English'}</button><button id="settings">${t('settings')} <span aria-hidden="true">⚙</span></button></nav></header><div class="menu-content"><section class="menu-story"><div class="eyebrow"><span class="status-dot"></span>25°04′ N · 121°14′ E &nbsp; / &nbsp; TAIWAN</div><h1>Taoyuan<br><span>Tower.</span></h1><h2>${t('tagline')}</h2><p>${t('description')}</p><div class="location-line"><div><div class="number">RCTP</div><small>TAIPEI FIR</small></div><div class="divider"></div><small>05L / 23R<br><br>05R / 23L</small><div class="divider"></div><small>GROUND · TOWER<br><br>APPROACH · DEPARTURE</small></div></section><section class="briefing"><div class="briefing-tabs">${[['new','newShift'],['training','training'],['sandbox','sandbox'],['explore','exploreMode']].map(([m,k])=>`<button data-mode="${m}" class="${mode===m?'active':''}">${t(k)}</button>`).join('')}</div><div class="briefing-body"><div class="briefing-heading"><span class="eyebrow">${t('scenario')}</span><span class="mono">TPE / RCTP</span></div><form id="scenario-form"><div class="form-grid"><label class="field full">${t('preset')}<select name="preset">${options(['morning','midday','evening','night','custom'],scenario.startTime==='06:00'?'morning':scenario.startTime==='12:00'?'midday':scenario.startTime==='22:00'?'night':scenario.startTime==='17:00'?'evening':'custom')}</select></label><label class="field">${t('date')}<input type="date" name="date" required value="${scenario.date}" min="2026-01-01" max="2030-12-31"/></label><label class="field">${t('startTime')}<input type="time" name="time" required value="${scenario.startTime}"/></label><label class="field">${t('duration')}<select name="duration" ${mode!=='new'?'disabled':''}>${[15,30,60,0].map((n,i)=>`<option value="${n}" ${Number(mode!=='new'?0:scenario.duration)===n?'selected':''}>${t(['quick','standardShift','full','unlimited'][i])}</option>`).join('')}</select></label><label class="field">${t('difficulty')}<select name="difficulty" ${mode==='explore'?'disabled':''}>${options(['assisted','standard','advanced','hardcore'],mode==='explore'?'assisted':scenario.difficulty)}</select></label><p id="difficulty-note" class="difficulty-note">${mode==='explore'?t('exploreDescription'):difficultyDescription(scenario.difficulty)}</p><label class="field full">${t('weather')}<select name="weather">${options(['random',...weatherOptions],scenario.weather)}</select></label><div class="field full">${t('positions')}<div class="position-checks">${roles.map(r=>`<label><input type="checkbox" name="position" value="${r}" ${mode==='explore'?'disabled':''} ${mode!=='explore'&&scenario.positions.includes(r)?'checked':''}/>${t(r)}</label>`).join('')}</div></div></div><button class="primary start-button" type="submit"><span>${t(mode==='training'?'training':mode==='explore'?'exploreStart':'enter')}</span><span aria-hidden="true">↗</span></button></form><div class="dataset-note" id="schedule-source">${scheduleNoteHTML(scenario.date)}</div></div></section></div><footer class="menu-footer"><span>${t('snapshot')} &nbsp; / &nbsp; VERTICAL SLICE 01</span><button class="ghost" id="sources">${t('sources')} ↗</button><span>WEBGL 2 · LOCAL SIMULATION</span></footer></main>`;
  $('#language').onclick=toggleLanguage;$('#settings').onclick=settings;$('#sources').onclick=sources;
  document.querySelectorAll<HTMLButtonElement>('[data-mode]').forEach(b=>b.onclick=()=>{readScenario();mode=b.dataset.mode!;renderMenu();});
  const form=$<HTMLFormElement>('#scenario-form');form.onchange=e=>{const el=e.target as HTMLInputElement;if(el.name==='preset'){const values:Record<string,string>={morning:'06:00',midday:'12:00',evening:'17:00',night:'22:00'};if(values[el.value])(form.elements.namedItem('time') as HTMLInputElement).value=values[el.value];}readScenario();if($('#difficulty-note'))$('#difficulty-note').textContent=mode==='explore'?t('exploreDescription'):difficultyDescription(scenario.difficulty);if($('#schedule-source'))$('#schedule-source').innerHTML=scheduleNoteHTML(scenario.date);};
  form.onsubmit=e=>{
   e.preventDefault();readScenario();
   if(sceneLoaded){begin();return;}
   const button=form.querySelector<HTMLButtonElement>('.start-button')!;
   if(button.disabled)return;
   const label=button.firstElementChild!,originalLabel=label.textContent;
   button.disabled=true;button.setAttribute('aria-busy','true');
   label.textContent=bi('Loading RCTP…','載入桃園機場中…');
   void audio.start().then(()=>{if(!running)audio.stop();},()=>{});
   void sceneReady.then(()=>{
    if(!form.isConnected)return;
    button.disabled=false;button.removeAttribute('aria-busy');label.textContent=originalLabel;
    begin();
   },()=>{});
  };
}
function readScenario(){const form=$<HTMLFormElement>('#scenario-form');if(!form)return;const data=new FormData(form);scenario={...scenario,date:String(data.get('date')||scenario.date),startTime:String(data.get('time')||scenario.startTime),duration:mode==='new'?Number(data.get('duration')??15):scenario.duration,difficulty:String(data.get('difficulty')??scenario.difficulty) as Scenario['difficulty'],weather:String(data.get('weather')) as Scenario['weather'],positions:mode==='explore'?scenario.positions:data.getAll('position') as Role[],tutorial:mode==='training'};}
function begin(){
  if(mode!=='explore'&&!scenario.positions.length&&scenario.difficulty!=='assisted'){toast(lang==='en'?'Select at least one controlled position, or choose Assisted for an AI watch.':'請選擇至少一個管制席，或選用輔助模式觀察 AI 作業。');return;}
  const config=mode==='explore'?explorationScenario(scenario):{...scenario,exploration:false,tutorial:mode==='training',duration:mode==='new'?scenario.duration:0,incidents:mode==='training'?'off' as const:scenario.incidents};
  sim.reset(config);audio.reset(sim);
  selectedId=null;role=scenario.positions.includes('Ground')?'Ground':scenario.positions[0]??'Ground';running=true;intro=true;last=undefined;uiElapsed=0;tutorialStage=0;tutorialDep=null;tutorialArr=null;detailKey='';listKey='';void audio.start().catch(()=>{});
  requestFrame();
  if(mode==='explore'){intro=false;immersive=true;exploreLocation='runway';exploreLabels=false;scene.setImmersive(true);scene.goToExploreSpot(exploreLocation);sim.timeScale=1;renderExploreHUD();refreshExploreUI();return;}
  sim.timeScale=0;app.innerHTML=`<div class="intro-title"><div class="eyebrow">${t('airport')}</div><h2>${t('tower')}</h2><p>${esc(scenario.date)} &nbsp; ${esc(scenario.startTime)} LT &nbsp; / &nbsp; ${scheduleName(scenario.date)}</p></div><button class="intro-skip" id="skip-intro">${t('skipIntro')}</button>`;
  $('#skip-intro').onclick=finishIntro;scene.startIntro();
}
function finishIntro(){if(!intro)return;intro=false;scene.skipIntro();sim.timeScale=1;renderHUD();refreshUI();}

function renderExploreHUD(){
 app.innerHTML=`<main class="explore-hud">
  <header class="explore-top"><div class="explore-brand">${logoHTML()}<span class="explore-badge"><span class="status-dot"></span>${bi('AI CONTROLLERS ACTIVE','AI 自動管制中')}</span></div>
   <div class="explore-top-actions"><span id="explore-clock" class="mono"></span><div class="explore-speed" aria-label="${bi('Simulation speed','模擬速度')}">${[0,1,2,4].map(n=>`<button data-explore-speed="${n}" title="${n===0?t('pause'):n+'×'}">${n===0?'Ⅱ':n+'×'}</button>`).join('')}</div><button id="explore-labels"></button><button id="explore-exit">${bi('Exit','結束漫遊')}</button></div>
  </header>
  <section class="explore-panel"><label for="explore-location">${bi('GO TO','快速移動')}</label><select id="explore-location" aria-label="${bi('Choose a location','選擇觀景位置')}">${[{label:bi('Passenger halls & airport views','旅客主要空間與機場觀景'),spots:primaryExploreSpots},{label:bi('Detailed inspection views','細部觀景位置'),spots:detailExploreSpots}].map(group=>`<optgroup label="${group.label}">${group.spots.map(s=>`<option value="${s.id}" ${s.id===exploreLocation?'selected':''}>${esc(lang==='en'?s.en:s.zh)}</option>`).join('')}</optgroup>`).join('')}</select><small id="explore-traffic"></small></section>
  <div class="explore-help">${bi('W A S D / arrows · walk   |   Drag mouse · look   |   Shift · walk faster   |   Space · pause','W A S D／方向鍵：走動　｜　按住滑鼠左鍵拖曳：轉向　｜　Shift：快走　｜　空白鍵：暫停')}</div>
  <div class="explore-paused" id="explore-paused" hidden>${t('paused')}</div>
 </main>`;
 $('#explore-location').onchange=e=>{exploreLocation=(e.target as HTMLSelectElement).value as ExploreSpotId;scene.goToExploreSpot(exploreLocation);};
 document.querySelectorAll<HTMLButtonElement>('[data-explore-speed]').forEach(b=>b.onclick=()=>{sim.timeScale=Number(b.dataset.exploreSpeed);refreshExploreUI();});
 $('#explore-labels').onclick=()=>{exploreLabels=!exploreLabels;scene.setImmersive(!exploreLabels);refreshExploreUI();};
 $('#explore-exit').onclick=()=>{sim.timeScale=0;renderMenu();};
}
function refreshExploreUI(){
 const time=document.querySelector<HTMLElement>('#explore-clock');if(!time)return;
 time.textContent=clock(sim.time);
 $('#explore-traffic').textContent=bi(`${sim.aircraft.filter(a=>!a.completed).length} active flights · ${sim.scores.departures} departures · ${sim.scores.arrivals} arrivals`,`${sim.aircraft.filter(a=>!a.completed).length} 架動態航機 · ${sim.scores.departures} 架起飛 · ${sim.scores.arrivals} 架抵達`);
 $('#explore-labels').textContent=exploreLabels?bi('Hide labels','隱藏標籤'):bi('Flight labels','航班標籤');
 $('#explore-paused').hidden=sim.timeScale!==0;
 document.querySelectorAll<HTMLButtonElement>('[data-explore-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.exploreSpeed)===sim.timeScale));
}

function renderHUD(){
  detailKey='';listKey='';
  app.innerHTML=`<main class="hud ${immersive?'immersion':''}"><header class="topbar">${logoHTML()}<nav class="role-nav" aria-label="${t('positions')}">${roles.map(r=>`<button data-role="${r}" class="${role===r?'active':''}" title="${t(r)}">${t(r)}</button>`).join('')}</nav><div class="top-right"><div class="clock"><small>${t('time')}</small><strong class="mono" id="clock">17:00:00</strong></div><div class="time-controls">${[0,1,2,4,8].map(n=>`<button data-speed="${n}" title="${n===0?t('pause'):n+'×'}" class="${sim.timeScale===n?'active':''}">${n===0?'Ⅱ':n+'×'}</button>`).join('')}</div><div class="safety-pill">${t('safety')}<strong id="safety-score">100</strong></div><button class="icon" id="hud-mode" title="${immersive?t('hud'):t('immersive')}">▣</button><button class="icon" id="settings" title="${t('settings')}">⚙</button><button class="operations-launch" id="operations-open">${bi('Operations','作業總覽')}</button><button class="small" id="end-shift">${t('endShift')}</button></div></header><section class="panel traffic-panel"><div class="panel-title">${t('traffic')}<small id="traffic-count">0</small><button class="ghost small" id="gate-board">${lang==='en'?'Gates':'機位'} ↗</button></div><div class="traffic-tabs"><button data-traffic-tab="flights" class="${trafficTab==='flights'?'active':''}">${bi('Flights','航班')}</button><button data-traffic-tab="requests" class="${trafficTab==='requests'?'active':''}">${bi('Requests','請求')} <span id="request-count"></span></button></div><div class="traffic-tools" ${trafficTab==='requests'?'hidden':''}><div class="traffic-filters">${[['all','all'],['departure','departures'],['arrival','arrivals']].map(([f,k])=>`<button data-filter="${f}" class="${filter===f?'active':''}">${t(k)}</button>`).join('')}</div><input id="search" aria-label="${t('search')}" placeholder="${t('search')}" value="${esc(query)}"/></div><div class="traffic-list" id="traffic-list" ${trafficTab==='requests'?'hidden':''}></div><div class="request-list" id="request-list" ${trafficTab==='flights'?'hidden':''}></div><div class="traffic-summary" id="traffic-summary">${t('typical')}</div></section><section class="panel command-panel" id="command-panel"></section><div class="view-caption"><span class="view-name" id="view-name">${t('seat').toUpperCase()}</span><span id="shift-remaining"></span></div><div class="camera-toolbar"><div class="camera-group">${cameras.map(([c,k,n])=>`<button data-camera="${c}" title="${n} · ${t(k)}" class="${scene.cameraMode===c?'active':''}">${t(k)}</button>`).join('')}</div></div><div class="footer-key">${t('cameraHelp')}</div><div class="bottom-panels"><section class="panel surface-panel"><div class="panel-title">${t('surface')}<small>RCTP</small></div><canvas id="surface-map" width="500" height="300" aria-label="${t('surface')}"></canvas><span class="map-legend">N ↗ &nbsp; · &nbsp; ${t('flow')} <span id="map-flow">05</span></span></section><section class="panel radio-panel"><div class="panel-title">${t('radio')}<small id="frequency">121.700</small></div><div class="radio-feed" id="radio-feed" role="log" aria-live="off"></div></section><section class="panel weather-panel"><div class="weather-top"><strong id="weather-name">${t('cloudy')}</strong><span id="wind-reading" class="mono">050° / 08 KT</span></div><div class="runway-status" id="runway-status"></div><div class="weather-meta"><span id="visibility-reading"></span><button id="weather-settings">${t('recommend')} <span id="recommendation">05</span> ↗</button></div></section></div><div id="pause-container"></div><div id="tutorial-container"></div>${immersive?`<div class="immersive-hint">${t('immersiveHint')}</div>`:''}</main>`;
  document.querySelectorAll<HTMLButtonElement>('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role as Role;renderHUD();refreshUI();});
  document.querySelectorAll<HTMLButtonElement>('[data-speed]').forEach(b=>b.onclick=()=>{sim.timeScale=Number(b.dataset.speed);refreshUI();});
  document.querySelectorAll<HTMLButtonElement>('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter!;renderHUD();refreshUI();});
  document.querySelectorAll<HTMLButtonElement>('[data-camera]').forEach(b=>b.onclick=()=>camera(b.dataset.camera as CameraMode));
  $<HTMLInputElement>('#search').oninput=e=>{query=(e.target as HTMLInputElement).value;listKey='';refreshUI();};
  $('#operations-open').onclick=()=>operationsDialog();
  document.querySelectorAll<HTMLButtonElement>('[data-traffic-tab]').forEach(b=>b.onclick=()=>{trafficTab=b.dataset.trafficTab as typeof trafficTab;renderHUD();refreshUI();});
  $('#request-list').onclick=e=>{const b=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-request]');if(!b)return;const request=sim.getOperations().requests.find(r=>r.id===b.dataset.request);if(request?.aircraftId)selectAircraft(request.aircraftId);if(request?.kind==='priority')operationsDialog();else if(request?.kind==='configuration')weatherDialog();else if(request?.kind==='gate'){const a=sim.aircraft.find(a=>a.id===request.aircraftId);if(a)routeDialog(a);}};
  $('#gate-board').onclick=gateBoard;$('#settings').onclick=settings;$('#weather-settings').onclick=weatherDialog;$('#end-shift').onclick=()=>showSummary();$('#hud-mode').onclick=toggleImmersive;
  $('#surface-map').onclick=e=>{const canvas=$<HTMLCanvasElement>('#surface-map');const rect=canvas.getBoundingClientRect();const p={x:(e.clientX-rect.left)/rect.width*500,z:(e.clientY-rect.top)/rect.height*300};let best:Aircraft|null=null,d=25;for(const a of sim.aircraft.filter(a=>!a.completed)){const m=mapPoint(a.position.x,a.position.z);const n=Math.hypot(m.x-p.x,m.y-p.z);if(n<d){d=n;best=a;}}if(best)selectAircraft(best.id);};
}
function selectAircraft(id:string){if(!running||intro||mode==='explore')return;const a=sim.aircraft.find(a=>a.id===id);if(!a)return;selectedId=id;role=a.role;detailKey='';listKey='';document.querySelectorAll<HTMLButtonElement>('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===role));refreshUI();audio.click();}
function camera(mode:CameraMode){if(['follow','orbit','gate'].includes(mode)&&!selectedId){const first=sim.aircraft.find(a=>!a.completed);if(first)selectAircraft(first.id);}scene.setCamera(mode);document.querySelectorAll<HTMLButtonElement>('[data-camera]').forEach(b=>b.classList.toggle('active',b.dataset.camera===mode));if($('#view-name'))$('#view-name').textContent=t(cameras.find(c=>c[0]===mode)?.[1]??'seat').toUpperCase();}
function toggleImmersive(){immersive=!immersive;scene.setImmersive(immersive);if(immersive)camera('seat');renderHUD();refreshUI();}

function refreshUI(){if(!running||intro)return;if(mode==='explore'){refreshExploreUI();return;}if(!$('#clock'))return;
  $('#clock').textContent=clock(sim.time);$('#safety-score').textContent=String(Math.round(sim.scores.safety));$('#traffic-count').textContent=String(sim.aircraft.filter(a=>!a.completed).length);
  $('#shift-remaining').textContent=sim.scenario.duration?`${Math.max(0,Math.ceil(sim.scenario.duration-sim.elapsed/60))} ${t('minutes')} ${t('remaining')}`:t('sandbox').toUpperCase();
  document.querySelectorAll<HTMLButtonElement>('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===sim.timeScale));
  $('#pause-container').innerHTML=sim.timeScale===0?`<div class="pause-banner">${t('paused')}</div>`:'';
  const visible=sim.aircraft.filter(a=>!a.completed&&(filter==='all'||a.kind===filter)&&(!query||`${a.callsign} ${a.flightNumber} ${carrierName(a.airline)}`.toLowerCase().includes(query.toLowerCase())));
  const nextListKey=visible.map(a=>[a.id,a.state,a.held,a.gate,a.runway,a.id===selectedId].join(':')).join('|')+lang;
  if(nextListKey!==listKey){listKey=nextListKey;$('#traffic-list').innerHTML=visible.length?visible.map(a=>`<button class="strip ${a.id===selectedId?'selected':''} ${sim.scenario.tutorial&&tutorialStage<=1&&a.kind==='departure'?'tutorial-glow':''}" data-aircraft="${a.id}" style="--airline-color:${AIRLINES[a.airline]?.color??'#b5cfbe'}"><div class="strip-top"><strong class="mono">${esc(a.callsign)}</strong><small>${esc(a.flightSource?(a.publishedType??bi('MODEL N/P','機型未公布')):a.type)}</small></div><div class="strip-bottom"><span class="${/REQUEST|READY|HOLDING_SHORT|GROUND_CONTACT/.test(a.state)?'request':''}">${stateLabel(a.state,lang)}</span><span class="kind">${a.kind==='departure'?'↗':'↙'} ${a.kind==='departure'?esc(a.destination):esc(a.origin)}</span></div><div class="strip-bottom"><small>${esc(a.flightSource?(a.scheduledGate||a.gate):a.gate||'—')} &nbsp; · &nbsp; ${esc(runwayName(a))}</small><small>${flightTimeLabel(a)}</small></div></button>`).join(''):`<div class="empty-selection">${t('noTraffic')}</div>`;document.querySelectorAll<HTMLButtonElement>('[data-aircraft]').forEach(b=>b.onclick=()=>selectAircraft(b.dataset.aircraft!));}
  $('#traffic-summary').textContent=`${t('workload')} ${Math.round(100-sim.scores.workload)}% · ${sim.scores.departures+sim.scores.arrivals} ${lang==='en'?'handled':'架完成'}`;
  renderSelected();refreshOperationsUI();
  $('#frequency').textContent=({Ground:'121.700',Tower:'118.700',Delivery:'121.800',Approach:'APP • SIM',Departure:'DEP • SIM'} as Record<Role,string>)[role];
  const feed=$('#radio-feed');const messages=sim.radio.slice(0,18).reverse();const latest=messages.at(-1)?.id; if(feed.dataset.latest!==String(latest)){const nearBottom=feed.scrollHeight-feed.scrollTop-feed.clientHeight<35;feed.dataset.latest=String(latest);feed.innerHTML=messages.map(m=>`<div class="radio-message ${m.level}"><span class="timestamp mono">${shortTime(m.time)}</span><span class="text">${esc(m.text)}</span></div>`).join('');if(nearBottom)feed.scrollTop=feed.scrollHeight;}
  $('#weather-name').textContent=t(sim.weather.kind);$('#wind-reading').textContent=`${String(Math.round(sim.weather.windDirection)).padStart(3,'0')}° / ${Math.round(sim.weather.windSpeed)} KT`;
  $('#visibility-reading').textContent=`${t('visibility')} ${(sim.weather.visibility/1000).toFixed(1)} KM`;$('#recommendation').textContent=sim.recommendedDirection;$('#map-flow').textContent=sim.activeDirection;
  $('#runway-status').innerHTML=airport.runways.map(r=>{const occ=sim.runwayOccupancy.get(r.id)??[];return `<button class="${occ.length?'busy':''}" data-runway="${r.id}"><strong class="mono">${sim.activeDirection==='05'?r.ends[0]:r.ends[1]}</strong><small><span class="status-dot" style="background:${occ.length?'#dfad7e':'#b7d0ac'}"></span>${t(occ.length?'occupied':'available')}</small></button>`;}).join('');document.querySelectorAll<HTMLButtonElement>('[data-runway]').forEach(b=>b.onclick=()=>{const id=sim.runwayOccupancy.get(b.dataset.runway!)?.[0];if(id)selectAircraft(id);camera('runway');});
  drawMap();updateTutorial();if(sim.ended&&!document.querySelector('.modal-backdrop'))showSummary();
}
function runwayName(a:Aircraft){const r=airport.runways.find(r=>r.id===a.runway);return r?(sim.activeDirection==='05'?r.ends[0]:r.ends[1]):a.runway;}
function renderSelected(){const a=sim.aircraft.find(a=>a.id===selectedId);const panel=$('#command-panel');if(!a){if(detailKey!=='empty'){detailKey='empty';panel.innerHTML=`<div class="panel-title">${t('flight')}</div><div class="empty-selection"><div class="plane">↗</div><strong>${t('noSelected')}</strong>${t('selectHint')}</div>`;}return;}
  const commands=sim.availableCommands(a.id);const key=[a.id,a.state,a.held,a.gate,a.runway,a.clearance,role,...commands,...a.routeNames,lang].join('|');if(key===detailKey)return;detailKey=key;
  const airline=AIRLINES[a.airline];const profile=FLEET[a.type];
  const modelLabel=a.flightSource?(a.publishedType??bi('Not published','未公布')):(profile?.name??a.type);
  const gateLabel=a.scheduledGate?(a.scheduledGate===a.gate?a.scheduledGate:`${a.scheduledGate} · sim ${a.gate}`):(a.gate||'—');
  const officialLine=a.flightSource?`<p class="info-note">${bi('Official TPE schedule','桃園機場官方班表')} · ${esc(flightStatusLabel(a.flightStatus))} · ${bi('scheduled','表定')} ${shortTime(a.publishedScheduledTime??a.scheduledTime)}${a.publishedScheduledTime!==undefined&&a.publishedScheduledTime!==a.scheduledTime?` · ${bi('updated','預計')} ${shortTime(a.scheduledTime)}`:''} · ${bi('airframe movement profile is approximate','機型移動參數為模擬近似')}</p>`:'';
  panel.innerHTML=`<div class="panel-title">${t('flight')}<small>${t(a.role)}</small></div><div class="aircraft-card"><div class="aircraft-card-header"><div class="airline-tail" style="background:${airline?.color??'#658a7a'}">${esc(airline?.prefix??a.airline)}</div><div><h2 class="mono">${esc(a.callsign)}</h2><div class="airline-name">${esc(carrierName(a.airline))} · ${esc(a.flightNumber)}</div></div></div><div class="route-line">${esc(a.origin)} <span>― ${a.kind==='departure'?'↗':'↙'} ―</span> ${esc(a.destination)}</div><div class="detail-grid"><div><small>${t('gate')}</small><strong>${esc(gateLabel)}</strong></div><div><small>${t('runway')}</small><strong>${esc(runwayName(a))}</strong></div><div><small>${t('weight')}</small><strong>${(a.weight/1000).toFixed(1)} t</strong></div><div><small>${t('wake')}</small><strong>${profile?.wake==='H'?'HEAVY':'MEDIUM'} / ${esc(modelLabel)}</strong></div></div>${officialLine}<div class="state-badge"><span class="status-dot"></span>${stateLabel(a.state,lang)}${a.held?' · HOLD':''}</div></div><div id="selected-operations" class="ops-selected"></div><div class="commands"><div class="eyebrow">${t('commands')}</div><div class="command-buttons">${role!==a.role?`<button id="switch-aircraft-role" class="primary">${t('switchRole')} →</button>`:commands.length?commands.map((cmd,i)=>`<button data-command="${cmd}" class="${i===0?'primary':/goAround|cancelTakeoff/.test(cmd)?'danger':'muted-command'}"><span>${commandLabel(cmd,lang)}</span><span>${i===0?'↗':'›'}</span></button>`).join(''):`<div class="awaiting">${t('awaiting')}<br><span class="mono">${esc(a.clearance)}</span></div>`}</div></div>${a.routeNames.length?`<div class="selected-route"><span class="eyebrow">${t('route')}</span><br>${a.routeNames.map(esc).join(' → ')}</div>`:''}<div class="command-footer"><button id="inspect-route">${t('inspectRoute')}</button><button id="follow-selected">${t('follow')}</button></div>`;
  document.querySelectorAll<HTMLButtonElement>('[data-command]').forEach(b=>b.onclick=()=>issue(a.id,b.dataset.command as Command));
  if($('#switch-aircraft-role'))$('#switch-aircraft-role').onclick=()=>{role=a.role;renderHUD();refreshUI();};$('#inspect-route').onclick=()=>routeDialog(a);$('#follow-selected').onclick=()=>camera('follow');
}
function issue(id:string,cmd:Command,override=false,value?:number|string){
  const a=sim.aircraft.find(a=>a.id===id);if(!a)return;
  if(!override&&cmd==='taxi'&&value===undefined){
    const proposals=sim.proposeRoutes(a.id),viable=proposals.filter(p=>p.nodes.length);
    if(viable.length&&viable[0].id&&!routeChoiceIsMaterial(viable)){
      issue(id,cmd,false,'route:'+viable[0].id);return;
    }
    routeDialog(a,cmd);return;
  }
  if(!override&&cmd==='taxiToGate'&&value===undefined){routeDialog(a,cmd);return;}
  if(value===undefined&&['heading','altitude','speed'].includes(cmd)){vectorDialog(a,cmd);return;}
  const result=sim.command(id,cmd,override,value);if(!result.ok&&result.warning){modal(t('warning'),`<div class="warning-sign">⚠</div><p>${esc(result.warning)}</p><p class="info-note">${t('warningNote')}</p>`,`<button data-cancel>${t('cancel')}</button><button class="danger" data-override>${t('override')}</button>`);$('[data-cancel]').onclick=closeModal;$('[data-override]').onclick=()=>{closeModal();issue(id,cmd,true,value);};}else if(!result.ok){toast(result.reason??result.warning??'Clearance unavailable');}else{audio.click();detailKey='';refreshUI();}
}
function routeChoiceIsMaterial(proposals:ReturnType<Simulation['proposeRoutes']>):boolean{
  if(proposals.length<2)return false;
  const first=proposals[0],crossings=(p:typeof first)=>(p.crossings??[]).slice().sort().join('|');
  return proposals.slice(1).some(p=>crossings(p)!==crossings(first)||(p.conflicts??0)!==(first.conflicts??0)||Math.abs((p.estimatedSeconds??0)-(first.estimatedSeconds??0))>=30||Math.abs(p.distance-first.distance)>=250);
}
function routeDialog(a:Aircraft,cmd?:Command){
  const eligible=airport.gates.filter(g=>g.maxSpan>=(FLEET[a.type]?.span??0));let proposals=sim.proposeRoutes(a.id,a.gate),choice=proposals[0]?.id;
  const renderProposal=()=>proposals.length?proposals.map((p,i)=>p.nodes.length?`<label class="route-option"><input type="radio" name="taxi-route" value="${p.id}" ${p.id===choice?'checked':''}/><span><strong>${bi('ROUTE','路線')} ${String.fromCharCode(65+i)} ${p.recommended?'· '+bi('Recommended','建議'):''}</strong><small>${p.names.map(esc).join(' → ')}<br>${(p.distance/1000).toFixed(2)} km · ~${duration(p.estimatedSeconds??0)} · ${p.conflicts??0} ${bi('reserved segments','已預約路段')}<br>${p.crossings?.length?bi('Runway crossings: ','穿越跑道：')+p.crossings.join(', '):bi('No runway crossing','無跑道穿越')}${p.warning?'<br>'+esc(p.warning):''}</small></span></label>`:`<p class="ops-note caution">${esc(p.warning)}</p>`).join(''):`<p>${bi('No compatible route available.','目前沒有相容的滑行路線。')}</p>`;
  const canPlan=a.kind==='arrival'&&['APPROACH','FINAL','LANDING_CLEARED','GO_AROUND','GROUND_CONTACT'].includes(a.state);
  modal(t('routePreview'),`${a.kind==='arrival'?`<label class="field">${t('assignGate')}<select id="route-gate">${eligible.map(g=>`<option value="${g.id}" ${a.gate===g.id?'selected':''}>${g.id} · ${g.terminal} ${sim.gateOccupancy.has(g.id)&&sim.gateOccupancy.get(g.id)!==a.id?'— '+t('occupied'):''}</option>`).join('')}</select></label><br>`:''}<div id="route-details">${renderProposal()}</div>`,`${cmd?`<button id="accept-route" class="primary" ${!proposals[0]?.nodes.length?'disabled':''}>${t('acceptRoute')}</button>`:canPlan?`<button id="accept-gate" class="primary">${bi('Assign planned stand','指定預計機位')}</button>`:`<button data-done>${t('close')}</button>`}`);
  $('#route-details').onchange=e=>{choice=(e.target as HTMLInputElement).value;};
  if($('#route-gate'))$<HTMLSelectElement>('#route-gate').onchange=()=>{proposals=sim.proposeRoutes(a.id,$<HTMLSelectElement>('#route-gate').value);choice=proposals[0]?.id;$('#route-details').innerHTML=renderProposal();if($('#accept-route'))$<HTMLButtonElement>('#accept-route').disabled=!proposals[0]?.nodes.length;};
  if($('#accept-route'))$('#accept-route').onclick=()=>{const gate=$<HTMLSelectElement>('#route-gate')?.value??a.gate;closeModal();issue(a.id,cmd!,false,cmd==='taxi'?'route:'+choice:gate+'@'+choice);};
  if($('#accept-gate'))$('#accept-gate').onclick=()=>{const result=sim.assignGate(a.id,$<HTMLSelectElement>('#route-gate').value);if(result.ok){closeModal();refreshUI();}else toast(result.reason??'');};
  if($('[data-done]'))$('[data-done]').onclick=closeModal;
}
function difficultyDescription(difficulty:Scenario['difficulty']){
  const descriptions:Record<Scenario['difficulty'],[string,string]>={assisted:['Lower traffic, automatic ground sequencing, recommended departure windows and gentle delay scoring.','低流量、自動地面排序、起飛空檔建議，延誤評分較寬鬆。'],standard:['Recommended. Traffic waves, operational predictions, route choices and important priority decisions.','建議模式。交通波段、作業預測、滑行路線選擇與重要優先權決策。'],advanced:['Peak traffic, manual priorities for major conflicts, fewer recommendations and stricter scoring.','尖峰流量，主要衝突須手動排序，減少建議並提高評分要求。'],hardcore:['Expert watch. Manual ground priorities and routine actions, minimal forecasts and stricter separation.','專家值勤。手動地面排序及例行操作、最低預測輔助與較嚴格間隔。']};return descriptions[difficulty][lang==='en'?0:1];
}
function operationsDialog(){
  modal(bi('AIRPORT OPERATIONS','機場作業總覽'),`<div id="operations-body"></div>`,`<button id="operations-plan">${bi('Pause & plan','暫停並規劃')}</button><button id="operations-debug">${bi('Ground debug','地面偵錯')}</button><button id="operations-resume" class="primary">${bi('Resume watch','恢復值勤')}</button>`,true);
  $('#operations-body').onclick=e=>{const target=e.target as HTMLElement,priority=target.closest<HTMLButtonElement>('[data-priority]'),flight=target.closest<HTMLButtonElement>('[data-ops-select]');if(priority){const result=sim.chooseGroundPriority(priority.dataset.priority!,priority.dataset.first==='auto'?undefined:priority.dataset.first);if(!result.ok)toast(result.reason??'');sim.getOperations(true);$('#operations-body').dataset.key='';refreshOperationsUI();}else if(flight){selectAircraft(flight.dataset.opsSelect!);closeModal();}};
  $('#operations-plan').onclick=()=>{if(sim.timeScale)previousScale=sim.timeScale;sim.timeScale=0;refreshUI();};$('#operations-resume').onclick=()=>{sim.timeScale=previousScale||1;closeModal();refreshUI();};$('#operations-debug').onclick=groundDebugDialog;refreshOperationsUI();
}
function groundDebugDialog(){
  const labels:Record<keyof GroundDebugOptions,[string,string]>={graph:['Taxi graph','滑行圖'],routes:['Aircraft routes','航機路線'],nodes:['Reserved nodes','預約節點'],edges:['Reserved edges','預約路段'],zones:['Conflict zones','衝突區域'],waits:['Wait dependencies','等待關係'],owners:['Priority owners','優先權持有者']};
  modal(bi('GROUND RESERVATIONS','地面預約偵錯'),`<div class="debug-toggles">${(Object.keys(groundDebug) as (keyof GroundDebugOptions)[]).map(k=>`<label><input type="checkbox" data-ground-layer="${k}" ${groundDebug[k]?'checked':''}/>${labels[k][lang==='en'?0:1]}</label>`).join('')}</div><label class="field">${bi('Inspect aircraft','檢視航機')}<select id="ground-debug-aircraft"><option value="">${bi('All traffic','所有交通')}</option>${sim.aircraft.filter(a=>!a.completed).map(a=>`<option value="${a.id}" ${selectedId===a.id?'selected':''}>${esc(a.callsign)} · ${a.state}</option>`).join('')}</select></label><canvas id="ground-debug-canvas" width="1200" height="460" aria-label="Ground reservation graph"></canvas><p class="ops-note">${bi('Colors identify owners. Thick lines / solid nodes are committed; dashed red lines show waiting dependencies. Amber squares are safe hold limits.','顏色代表持有航機；粗線及實心節點表示已進入。紅色虛線表示等待關係，橙色方塊表示安全等待界線。')}</p><div id="ground-debug-waits" class="ground-debug-waits"></div>`,`<button id="ground-debug-back">${bi('Operations','作業總覽')}</button>`,true);
  document.querySelectorAll<HTMLInputElement>('[data-ground-layer]').forEach(input=>input.onchange=()=>{groundDebug[input.dataset.groundLayer as keyof GroundDebugOptions]=input.checked;refreshOperationsUI();});$('#ground-debug-aircraft').onchange=()=>refreshOperationsUI();$('#ground-debug-back').onclick=operationsDialog;refreshOperationsUI();
}
function refreshOperationsUI(){
  const ops=sim.getOperations(),requests=$('#request-list');if($('#request-count'))$('#request-count').textContent=String(ops.requests.length);
  const requestKey=ops.requests.map(r=>`${r.id}:${r.urgency}:${Math.floor(r.age/5)}:${r.detail}`).join('|')+lang;
  if(requests&&requests.dataset.key!==requestKey){requests.dataset.key=requestKey;requests.innerHTML=requestHTML(sim,lang);}
  const selected=sim.aircraft.find(a=>a.id===selectedId);if(selected&&$('#selected-operations'))$('#selected-operations').innerHTML=selectedOperationsHTML(sim,selected,lang);
  const board=$('#operations-body'),boardKey=[Math.floor(sim.elapsed),sim.scores.decisions,sim.weather.kind,sim.weather.windDirection,lang,sim.ground.conflicts.length].join('|');
  if(board&&board.dataset.key!==boardKey){const focused=document.activeElement as HTMLElement,priority=focused?.dataset.priority,first=focused?.dataset.first;board.dataset.key=boardKey;board.innerHTML=operationsHTML(sim,lang);if(priority)Array.from(board.querySelectorAll<HTMLButtonElement>('[data-priority]')).find(b=>b.dataset.priority===priority&&b.dataset.first===first)?.focus({preventScroll:true});}
  if($('#operations-plan'))$('#operations-plan').textContent=sim.timeScale?bi('Pause & plan','暫停並規劃'):bi('Planning · paused','規劃中 · 已暫停');
  const canvas=$<HTMLCanvasElement>('#ground-debug-canvas');if(canvas){const id=$<HTMLSelectElement>('#ground-debug-aircraft').value||null;drawGroundDebug(sim,canvas,id,groundDebug);const waits=[...sim.ground.waits.values()].filter(w=>!id||w.aircraftId===id);$('#ground-debug-waits').innerHTML=waits.map(w=>`<div><strong>${esc(sim.aircraft.find(a=>a.id===w.aircraftId)?.callsign??w.aircraftId)}</strong> · ${bi('WAITING FOR','等待對象')}: ${esc(w.owners.map(id=>sim.aircraft.find(a=>a.id===id)?.callsign??id).join(', ')||bi('controller','管制員'))}<br>${bi('REASON','原因')}: ${esc(w.reason)} · ${bi('WAIT','等待')} ${duration(sim.elapsed-w.since)} · ${esc(w.zone)}</div>`).join('')||bi('No wait dependencies for this selection.','選定航機沒有等待關係。');}
}
function vectorDialog(a:Aircraft,cmd:Command){const limits=cmd==='heading'?[0,360,1,Math.round(a.heading*180/Math.PI+319.08)%360]:cmd==='altitude'?[1500,20000,500,5000]:[130,300,10,180];modal(commandLabel(cmd,lang),`<label class="field">${cmd==='heading'?'TRUE °':cmd==='altitude'?'ALT FT':'IAS KT'}<input type="number" id="vector-value" min="${limits[0]}" max="${limits[1]}" step="${limits[2]}" value="${limits[3]}"/></label>`,`<button class="primary" id="vector-apply">${commandLabel(cmd,lang)}</button>`);$('#vector-apply').onclick=()=>{const input=$<HTMLInputElement>('#vector-value');if(!input.checkValidity()){input.reportValidity();return;}const value=Number(input.value);closeModal();issue(a.id,cmd,false,value);};}
function settings(){modal(t('settings'),`<div class="row"><span>${t('language')}</span><button class="small" id="setting-language">${lang==='en'?'繁體中文':'English'}</button></div><div class="row"><label for="quality">${t('graphics')}</label><select id="quality">${options(['low','medium','high'],quality)}</select></div><div class="row"><label for="audio">${t('audio')}</label><input type="checkbox" id="audio" ${audio.enabled?'checked':''}/></div><div class="row"><label for="audio-volume">${bi('Volume','音量')}</label><input type="range" id="audio-volume" min="0" max="100" step="5" value="${Math.round(audio.volume*100)}"/></div><div class="row"><label for="radio-voice">${bi('Radio voice (local)','無線電語音（本機）')}</label><input type="checkbox" id="radio-voice" ${audio.radioVoice?'checked':''}/></div><div class="row"><label for="incidents">${t('incidents')}</label><select id="incidents">${[['off','off'],['rare','rare'],['normal','normal'],['training','incidentTraining']].map(([v,k])=>`<option value="${v}" ${(running?sim.scenario.incidents:scenario.incidents)===v?'selected':''}>${t(k)}</option>`).join('')}</select></div><div class="row"><label for="routine-automation">${bi('Routine engines, runway exits and handoffs','自動處理例行引擎、脫離與交接')}</label><input type="checkbox" id="routine-automation" ${routineEnabled(running?sim.scenario:scenario)?'checked':''} ${running&&sim.scenario.tutorial?'disabled':''}/></div><div class="row"><label for="scenario-seed">${t('seed')}</label><input id="scenario-seed" type="number" value="${scenario.seed}" ${running?'disabled':''}/></div><p class="info-note">${t('cameraHelp')}<br><span class="kbd">H</span> ${t('hud')} &nbsp; <span class="kbd">F3</span> ${t('debug')}</p>`,`<button id="setting-sources">${t('sources')}</button><button id="setting-debug">${t('debug')}</button><button class="primary" id="setting-done">${t('close')}</button>`);
  $<HTMLInputElement>('#routine-automation').onchange=e=>{const value=(e.target as HTMLInputElement).checked;scenario.routineAutomation=value;if(running)sim.scenario.routineAutomation=value;};
  $('#setting-language').onclick=toggleLanguage;$<HTMLSelectElement>('#quality').onchange=e=>{quality=(e.target as HTMLSelectElement).value as typeof quality;persist('atc-quality',quality);scene?.setQuality(quality);};$<HTMLInputElement>('#audio').onchange=e=>{audio.setEnabled((e.target as HTMLInputElement).checked);persist('atc-audio',audio.enabled);void audio.start().catch(()=>{});};$<HTMLInputElement>('#audio-volume').oninput=e=>{audio.setVolume(Number((e.target as HTMLInputElement).value)/100);persist('atc-volume',audio.volume);};$<HTMLInputElement>('#radio-voice').onchange=e=>{audio.setRadioVoice((e.target as HTMLInputElement).checked);persist('atc-radio-voice',audio.radioVoice);};$<HTMLSelectElement>('#incidents').onchange=e=>{const v=(e.target as HTMLSelectElement).value as Scenario['incidents'];scenario.incidents=v;sim.scenario.incidents=v;};$<HTMLInputElement>('#scenario-seed').onchange=e=>scenario.seed=Number((e.target as HTMLInputElement).value)||182731;$('#setting-done').onclick=closeModal;$('#setting-sources').onclick=sources;$('#setting-debug').onclick=()=>{if(!running){toast(lang==='en'?'Begin a shift to use scenario tools.':'請先開始值勤，再使用情境工具。');return;}debugDialog();};
}
function sources(){modal(t('sourcesHeading'),`<p>${t('sourcesText')}</p><p><a href="${airportSource.source}" target="_blank" rel="noreferrer">Taiwan CAA · eAIP AIRAC 05/26 ↗</a></p><p class="info-note">${lang==='en'?'Selected airport details use AIRAC 05/26, effective 29 October 2026, for published stand positions, taxiway pavement, runway dimensions, markings and lighting. The reduced taxi graph, stand lead-ins, terminal shells and interiors remain visual approximations; there is no live NOTAM feed. T3 is a completed-design visual preview. Flight data is exact to its dated snapshot; simulated movement and some stand matching are approximate.':'機場場景已採用 05/26（2026/10/29 生效）的停機位、滑行道鋪面、跑道尺寸、標線與燈光資料。簡化滑行圖、機位導引線、航廈外殼與室內配置仍是視覺近似，且未連接即時 NOTAM。第三航廈是完工設計視覺預覽。航班資料符合指定日期快照；滑行與部分機位對應仍為模擬近似。'}</p><p><a href="https://data.gov.tw/en/datasets/26194" target="_blank" rel="noreferrer">Taoyuan Airport flight data ↗</a> · <a href="https://data.gov.tw/en/license" target="_blank" rel="noreferrer">Open Government Data License v1.0 ↗</a></p><p><a href="docs/DATA_SOURCES.md" target="_blank">DATA_SOURCES.md</a> · <a href="docs/REALISM_NOTES.md" target="_blank">REALISM_NOTES.md</a> · <a href="docs/ASSET_PROVENANCE.md" target="_blank">ASSET_PROVENANCE.md</a></p>`);}
function weatherDialog(){modal(t('weather'),`<div class="form-grid"><label class="field full">${t('weather')}<select id="weather-kind">${options(weatherOptions,sim.weather.kind)}</select></label><label class="field">${t('wind')} °<input id="wind-direction" type="number" min="0" max="359" value="${Math.round(sim.weather.windDirection)}"/></label><label class="field">KT<input id="wind-speed" type="number" min="0" max="45" value="${Math.round(sim.weather.windSpeed)}"/></label></div><div class="row"><span>${t('flow')}</span><select id="runway-direction"><option ${sim.activeDirection==='05'?'selected':''}>05</option><option ${sim.activeDirection==='23'?'selected':''}>23</option></select></div><p class="info-note">${t('flowNote')}</p>`,`<button id="queue-flow">${bi('Plan after traffic clears','排程至交通清空後變更')}</button><button id="apply-flow">${t('applyFlow')}</button><button class="primary" id="apply-weather">${t('changeWeather')}</button>`);
  $('#queue-flow').onclick=()=>{sim.planDirection($<HTMLSelectElement>('#runway-direction').value as '05'|'23');closeModal();refreshUI();toast(bi('Configuration planned. Finish committed traffic; new departures wait.','已排定配置變更。請完成既有交通，新出發航機暫候。'));};
  $('#apply-weather').onclick=()=>{const d=$<HTMLInputElement>('#wind-direction'),s=$<HTMLInputElement>('#wind-speed');if(!d.reportValidity()||!s.reportValidity())return;sim.setWeather($<HTMLSelectElement>('#weather-kind').value as WeatherKind,Number(d.value),Number(s.value));closeModal();refreshUI();};$('#apply-flow').onclick=()=>{const result=sim.setDirection($<HTMLSelectElement>('#runway-direction').value as '05'|'23');if(!result.ok)toast(result.reason??result.warning??'Traffic must clear first');else{closeModal();refreshUI();}};
}
function debugDialog(){const a=sim.aircraft.find(a=>a.id===selectedId);modal(t('debug'),`<div class="row"><span>${t('seed')} <span class="mono">${sim.scenario.seed}</span></span><span class="mono">${Math.round(scene.fps??0)} FPS · 10 Hz SIM</span></div><label class="field">AIRCRAFT TYPE<select id="debug-type">${Object.entries(FLEET).map(([id,p])=>`<option value="${id}">${p.name}</option>`).join('')}</select></label><div class="debug-buttons"><button id="spawn-dep">${t('spawnDep')}</button><button id="spawn-arr">${t('spawnArr')}</button><button id="force-runway">${t('forceRunway')}</button><button id="trigger-conflict">${t('triggerConflict')}</button><button id="clear-traffic">${t('clearTraffic')}</button><button id="debug-weather">${t('weather')}</button><button id="debug-graph">${t('showGraph')} ${graph?'✓':''}</button><button id="debug-reservations">${bi('Ground reservations','地面預約偵錯')}</button><button id="debug-reset">${lang==='en'?'Reset scenario':'重設情境'}</button></div><div class="row"><label for="debug-time">${t('time')}</label><input type="time" id="debug-time" value="${shortTime(sim.time)}"/></div><button class="small" id="set-time">${t('changeTime')}</button><pre class="debug-state">${esc(a?JSON.stringify({callsign:a.callsign,state:a.state,position:a.position,speed:a.speed,role:a.role,route:a.route,routeIndex:a.routeIndex,clearance:a.clearance},null,2):'Select an aircraft to inspect its state.')}</pre>`);
  $('#debug-reservations').onclick=groundDebugDialog;
  $('#spawn-dep').onclick=()=>{const a=sim.spawn('departure',$<HTMLSelectElement>('#debug-type').value);if(a){selectAircraft(a.id);closeModal();}else toast('No compatible free stand.');};$('#spawn-arr').onclick=()=>{const a=sim.spawn('arrival',$<HTMLSelectElement>('#debug-type').value);if(a){selectAircraft(a.id);closeModal();}};$('#force-runway').onclick=()=>{sim.debugOccupyRunway();closeModal();refreshUI();};$('#trigger-conflict').onclick=()=>{sim.debugOccupyRunway();const a=sim.aircraft.find(a=>a.kind==='arrival'&&!a.completed&&['APPROACH','FINAL'].includes(a.state))||sim.spawn('arrival');closeModal();if(a){if(a.state==='APPROACH')sim.command(a.id,'clearApproach');if(a.role==='Approach')sim.command(a.id,'contactTower');selectAircraft(a.id);issue(a.id,'land');}};$('#clear-traffic').onclick=()=>{sim.clearTraffic();selectedId=null;closeModal();refreshUI();};$('#debug-weather').onclick=weatherDialog;$('#debug-graph').onclick=()=>{graph=!graph;scene.setGraphVisible(graph);closeModal();};$('#debug-reset').onclick=()=>{sim.reset(sim.scenario);selectedId=null;tutorialStage=0;tutorialDep=null;tutorialArr=null;closeModal();refreshUI();};$('#set-time').onclick=()=>{const parts=$<HTMLInputElement>('#debug-time').value.split(':').map(Number);sim.time=parts[0]*3600+parts[1]*60;closeModal();refreshUI();};}

function showSummary(){previousScale=sim.timeScale;sim.timeScale=0;const score=sim.getSummary();modal(t('shiftComplete'),`<div class="score-hero"><div><div class="eyebrow">${t('score')}</div><p>${t('shiftSummary')}</p><small>${sim.scenario.date} · ${Math.floor(sim.elapsed/60)} ${t('minutes')} · RCTP</small></div><div><strong>${Math.round(score.overall)}</strong><small>${t('overall')} / 100</small></div></div><div class="score-categories">${(['safety','efficiency','delay','passenger','workload'] as const).map(k=>`<div class="score-category"><strong>${Math.round(score[k])}</strong><small>${t(k)}</small><div class="score-meter"><span style="width:${score[k]}%"></span></div></div>`).join('')}</div><div class="row"><span>${t('departures')} <b>${score.departures}</b> &nbsp; ${t('arrivals')} <b>${score.arrivals}</b></span><span>${score.commands} ${lang==='en'?'clearances':'項許可'}</span></div><p class="score-secondary">${bi('Player decisions / commands','玩家決策／指令')}: ${score.decisions} / ${score.playerCommands} · ${bi('Routine actions automated','已自動處理例行操作')}: ${score.routineCommands}<br>${bi('Command efficiency','指令效率')}: ${Math.round(score.commandEfficiency)}% · ${bi('Decisions / min','每分鐘決策')}: ${score.decisionRate.toFixed(1)} · ${bi('Commands / min','每分鐘指令')}: ${score.commandRate.toFixed(1)}</p><div class="score-events">${score.events.length?score.events.slice(-12).map(e=>`${shortTime(e.time)} · ${esc(e.text)}<br>`).join(''):t('noEvents')}</div><p class="info-note">${t('suggestion')}</p>`,`<button id="summary-continue">${t(sim.ended?'continueSandbox':'resume')}</button><button class="primary" id="summary-menu">${t('returnMenu')}</button>`,true);
  $('#summary-continue').onclick=()=>{if(sim.ended){sim.scenario.duration=0;sim.ended=false;}sim.timeScale=previousScale||1;closeModal();refreshUI();};$('#summary-menu').onclick=()=>{sim.timeScale=1;scene.setCamera('free');renderMenu();};$('[data-close]').onclick=()=>{if(sim.ended){sim.scenario.duration=0;sim.ended=false;}sim.timeScale=previousScale||1;closeModal();};
}
function gateBoard(){
  const rows=airport.gates.map(g=>{const id=sim.gateOccupancy.get(g.id),a=sim.aircraft.find(a=>a.id===id);return `<tr><td class="mono">${g.id}</td><td>${g.terminal}</td><td>${g.maxSpan} m</td><td class="${id?'occupied-gate':'free-gate'}">${a?esc(a.callsign)+' · '+stateLabel(a.state,lang):t('available')}</td></tr>`;}).join('');
  modal(t('gate'),`<p>${sim.gateOccupancy.size} / ${airport.gates.length} ${t('occupied').toLowerCase()}</p><div class="gate-table-wrap"><table class="gate-table"><thead><tr><th>${t('gate')}</th><th>${lang==='en'?'Terminal':'航廈'}</th><th>${lang==='en'?'Span limit':'翼展限制'}</th><th>${t('status')}</th></tr></thead><tbody>${rows}</tbody></table></div><p class="info-note">${lang==='en'?'Select an arrival and use Taxi to assigned stand to inspect and change its stand. Wingspan caps and airline allocation are game rules.':'選取抵達航機，使用「滑行至指定機位」檢視或變更機位。翼展限制及航空公司分配為遊戲規則。'}</p>`,undefined,true);
}
const mapPoint=(x:number,z:number)=>({x:250+x*.096,y:143+z*.096});
function drawMap(){const canvas=$<HTMLCanvasElement>('#surface-map');if(!canvas)return;const ctx=canvas.getContext('2d')!;ctx.clearRect(0,0,500,300);ctx.fillStyle='#122932';ctx.fillRect(0,0,500,300);ctx.strokeStyle='#72918212';ctx.lineWidth=1;for(let x=10;x<500;x+=25){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,300);ctx.stroke();}for(let y=0;y<300;y+=25){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(500,y);ctx.stroke();}
  ctx.strokeStyle='#54777a66';ctx.lineWidth=1.4;for(const edge of airport.edges){const a=airport.nodes.find(n=>n.id===edge.from)!,b=airport.nodes.find(n=>n.id===edge.to)!;const p=mapPoint(a.x,a.z),q=mapPoint(b.x,b.z);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();}
  for(const r of airport.runways){const p=mapPoint(r.x-r.length/2,r.z),q=mapPoint(r.x+r.length/2,r.z);ctx.strokeStyle='#b7c6b1';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();ctx.fillStyle='#a6c3b6';ctx.font='12px Consolas';ctx.fillText(r.ends[0],p.x-30,p.y+4);ctx.fillText(r.ends[1],q.x+7,q.y+4);}
  for(const b of airport.terminals){const p=mapPoint(b.x,b.z);ctx.fillStyle=b.status==='construction'?'#ab906433':'#95b3af44';ctx.fillRect(p.x-b.width*.048,p.y-b.depth*.048,b.width*.096,b.depth*.096);}
  const sel=sim.aircraft.find(a=>a.id===selectedId);if(sel?.route.length){ctx.strokeStyle='#d5d491';ctx.lineWidth=2;ctx.beginPath();sel.route.forEach((id,i)=>{const n=airport.nodes.find(n=>n.id===id);if(n){const p=mapPoint(n.x,n.z);if(i)ctx.lineTo(p.x,p.y);else ctx.moveTo(p.x,p.y);}});ctx.stroke();}
  for(const a of sim.aircraft.filter(a=>!a.completed)){const p=mapPoint(a.position.x,a.position.z);if(p.x<0||p.x>500)continue;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a.heading);ctx.fillStyle=a.id===selectedId?'#f8e0a1':a.kind==='arrival'?'#87bfc7':'#c4d5ad';ctx.beginPath();ctx.moveTo(0,-6);ctx.lineTo(4,5);ctx.lineTo(0,2);ctx.lineTo(-4,5);ctx.closePath();ctx.fill();if(a.id===selectedId){ctx.strokeStyle='#f8e0a1';ctx.beginPath();ctx.arc(0,0,10,0,Math.PI*2);ctx.stroke();}ctx.restore();}
}

function updateTutorial(){const container=$('#tutorial-container');if(!container)return;if(!sim.scenario.tutorial){container.innerHTML='';return;}
  if(!tutorialDep)tutorialDep=sim.aircraft.find(a=>a.kind==='departure')?.id??null;
  const dep=sim.aircraft.find(a=>a.id===tutorialDep);
  if(tutorialStage===1&&selectedId===tutorialDep)tutorialStage=2;
  if(tutorialStage===2&&dep&&['READY_TO_TAXI','TAXI_CLEARED','TAXIING','HOLDING_SHORT'].includes(dep.state))tutorialStage=3;
  if(tutorialStage===3&&dep&&['TAXI_CLEARED','TAXIING','HOLDING_SHORT'].includes(dep.state))tutorialStage=4;
  if(tutorialStage===4&&dep?.state==='HOLDING_SHORT')tutorialStage=5;
  if(tutorialStage===5&&dep?.state==='READY_FOR_TAKEOFF')tutorialStage=6;
  if(tutorialStage===6&&dep&&['AIRBORNE','DEPARTURE','HANDED_OFF'].includes(dep.state))tutorialStage=7;
  if(tutorialStage===7&&(dep?.completed||sim.scores.departures>0)){tutorialStage=8;if(!sim.aircraft.some(a=>a.kind==='arrival'&&!a.completed))sim.spawn('arrival');}
  if(!tutorialArr&&tutorialStage>=8)tutorialArr=sim.aircraft.find(a=>a.kind==='arrival'&&!a.completed)?.id??null;
  const arr=sim.aircraft.find(a=>a.id===tutorialArr);
  if(tutorialStage===8&&arr?.role==='Tower'&&selectedId===arr.id)tutorialStage=9;
  if(tutorialStage===9&&arr&&['TOUCHDOWN','DECELERATING','VACATING_RUNWAY'].includes(arr.state))tutorialStage=10;
  if(tutorialStage===10&&arr&&['GROUND_CONTACT','TAXI_CLEARED','TAXIING_TO_GATE'].includes(arr.state))tutorialStage=11;
  if(tutorialStage===11&&arr&&['TAXIING_TO_GATE','ENTERING_STAND','PARKED','DOCKED'].includes(arr.state))tutorialStage=12;
  if(tutorialStage===12&&(arr?.state==='DOCKED'||arr?.completed||sim.scores.arrivals>0))tutorialStage=13;
  const keys=['tutorialIntro','tutorialIntro','tutorialPush','tutorialTaxi','tutorialHold','tutorialLine','tutorialTakeoff','tutorialDeparture','tutorialArrival','tutorialLand','tutorialVacate','tutorialGround','tutorialDock','tutorialSafety','tutorialScore'];
  const key=String(tutorialStage)+lang;if(container.dataset.stage===key)return;container.dataset.stage=key;
  const manual=[0,13,14].includes(tutorialStage);
  container.innerHTML=`<section class="tutorial-card"><div class="tutorial-top"><span class="eyebrow">${t('tutorial')} &nbsp; ${Math.min(14,tutorialStage+1)} / 14</span><button id="skip-tutorial">${t('skipTutorial')}</button></div><p>${t(keys[tutorialStage]??'tutorialFinish')}</p>${manual?`<div style="text-align:right;margin-top:10px"><button id="tutorial-next">${t(tutorialStage===14?'tutorialComplete':'next')} →</button></div>`:''}<div class="progress-track"><span style="width:${Math.min(100,tutorialStage/14*100)}%"></span></div></section>`;
  $('#skip-tutorial').onclick=()=>{sim.scenario.tutorial=false;container.innerHTML='';};if($('#tutorial-next'))$('#tutorial-next').onclick=()=>{if(tutorialStage===14){sim.scenario.tutorial=false;container.innerHTML='';toast(t('tutorialFinish'));}else{tutorialStage++;updateTutorial();}};
}

window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes((e.target as HTMLElement)?.tagName))return;if(e.key==='Escape'){closeModal();return;}if(!running)return;if(mode==='explore'){if(e.code==='Space'){e.preventDefault();sim.timeScale=sim.timeScale?0:1;refreshExploreUI();}return;}if(e.key==='F3'){e.preventDefault();debugDialog();return;}if(intro){if(e.code==='Space')finishIntro();return;}if(document.querySelector('.modal-backdrop'))return;if(e.code==='Space'){e.preventDefault();sim.timeScale=sim.timeScale?0:1;refreshUI();}if(e.key.toLowerCase()==='t')camera('seat');if(e.key.toLowerCase()==='h')toggleImmersive();const n=Number(e.key);if(n>=1&&n<=8)camera(cameras[n-1][0]);});
window.addEventListener('resize',()=>scene?.resize());

function requestFrame(){
 if(sceneLoaded&&!frameId)frameId=requestAnimationFrame(frame);
}
function frame(now:number){
 frameId=0;
 if(!running){
  // The browser retains the last composited frame until a resize, setting
  // change, or new session calls for another full-quality menu frame.
  scene.update(sim,selectedId,0);
  return;
 }
 const elapsed=last===undefined?0:(now-last)/1000,dt=Math.min(.1,elapsed);
 last=now;
 if(!intro)sim.update(dt);
 scene.update(sim,selectedId,dt,intro?elapsed:dt);
 if(intro&&scene.introFinished)finishIntro();
 if(!intro)audio.update(sim,scene.audioPosition());
 uiElapsed+=dt;
 if(uiElapsed>=.25){uiElapsed=0;refreshUI();}
 requestFrame();
}

async function initializeScene(){
  const {AirportScene}=await import('./render/AirportScene');
  scene=await AirportScene.create($('#scene'),selectAircraft,()=>{if(running&&mode!=='explore'){immersive=false;scene.setImmersive(false);renderHUD();refreshUI();}},requestFrame);
  scene.setQuality(quality);
  await scene.assetsReady;
  sceneLoaded=true;
  // Read-only references plus explicit simulation hooks aid deterministic local QA.
  Object.assign(window,{__ATC:{get sim(){return sim;},get scene(){return scene;},get selected(){return selectedId;},begin:(config?:Partial<Scenario>)=>{scenario={...scenario,...config};mode=config?.tutorial?'training':config?.duration===0?'sandbox':'new';begin();finishIntro();},select:selectAircraft,camera,refresh:refreshUI,get tutorialStage(){return tutorialStage;}}});
  requestFrame();
}

document.documentElement.lang=lang==='en'?'en':'zh-Hant';
renderMenu();document.querySelector('#loading')?.remove();
sceneReady=initializeScene();
void sceneReady.catch(error=>{console.error(error);app.innerHTML=`<div class="fatal"><h1>Taoyuan Tower</h1><p>The 3D renderer could not start. Enable hardware acceleration and WebGL 2 in a current Chrome or Edge browser, then reload.</p><pre>${esc(error instanceof Error?error.message:error)}</pre><button class="primary" onclick="location.reload()">Reload</button></div>`;});
